import React, { useEffect, useState } from 'react';
import styles from '../../style.module.less';
import { Button, Card, Descriptions, List, Message, Space, Tooltip } from '@arco-design/web-react';
import { AsyncButton } from '@/components/custom';
import { IconQuestionCircle } from '@arco-design/web-react/icon';
import ajax from '@/utils/ajax';


export default () => {

    const [list, setList] = useState([])

    const getList = () => {
        ajax.post('/apijson/get', {
            "AppVersion[]": {
                "count": 50,
                "AppVersion": {
                    "@order": "createdAt-",
                }
            }
        }).then((res) => {
            setList(res.AppVersion);
        })
    }

    useEffect(() => {
        getList();
    },[])

    return (
        <div className={styles.exploit}>
            <Space className={styles.header}>
                <AsyncButton type="primary"
                    onClick={() => {
                        return ajax.post('/app/version/create', {}).then(() => {
                            Message.success("部署成功");
                            getList();
                        });
                    }}
                >
                    一键部署
                    <Tooltip content="修改组建、多语言、查找项等相关内容后需要重新进行项目部署">
                        <IconQuestionCircle />
                    </Tooltip>
                </AsyncButton>
                <Button type="primary"
                    onClick={() => {
                        window.open(`#/run/`)
                    }}
                >
                    立即访问
                </Button>
            </Space>
            <List
                dataSource={list}
                className={styles.listBody}
                onReachBottom={() => {

                }}
                render={(item) => {
                    const { pages, modules, languages } = item.releaseNotes;
                    return (
                        <Card key={item.id} hoverable style={{ marginTop: 10 }}>
                            <Descriptions border
                                column={5}
                                colon=' :' layout='inline-horizontal'
                                title={`开发部署: ${item.updatedAt}`}
                                data={[
                                    {
                                        label: '提交人',
                                        value: item.userId,
                                    },
                                    {
                                        label: "部署影响页面",
                                        value: pages.length
                                    }, 
                                    {
                                        label: "部署影响组件",
                                        value: modules.length
                                    },
                                    {
                                        label: "部署影响多语言",
                                        value: languages
                                    }
                                ]} 
                            />
                        </Card>
                    )
                }}
                virtualListProps={{}}
            >
            </List>
        </div>
    )
}